# Generated by build.py from recipe.yml for recipe http-refuse-a-password-in-clear. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--user', 'alice:secret', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -u alice:secret -o NUL -w "%{http_code}" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
